// AUTO-GENERATED by a marching-squares extraction over real SRTM elevation
// data (open-elevation.com, sampled on a ~3km grid across Sri Lanka, retrieved
// 2026-08-04). Each band is the set of closed contour ring(s) where the real
// terrain crosses that elevation threshold, smoothed (Chaikin corner-cutting)
// and simplified (Douglas-Peucker) to a low-poly "cut paper contour" style
// matching ISLAND_MAIN_RING, then reprojected into the scene's world [x, z]
// space via the same project()+svgToWorld() pipeline. Do not hand-edit.

export interface TerrainBand {
  /** Real elevation (meters) this contour ring traces. */
  thresholdM: number;
  rings: [number, number][][];
}

